/**
 * Types and helpers for the `/` tutorial.
 *
 * The data itself is generated by `scripts/tutorial/build.mjs` into
 * `src/data/tutorial/generated/`; this module is the hand-written contract
 * between the generator, the pages and the browser script. `tests/tutorial.test.ts`
 * checks that the generated files still satisfy it.
 */

import indexJson from '@data/tutorial/generated/index.json';

export interface TutorialPart {
  id: string;
  label: string;
  title: string;
  blurb: string;
  from: string;
  to: string;
}

export interface TutorialChapterMeta {
  slug: string;
  number: string;
  title: string;
  summary: string;
  readingMinutes: number;
  exerciseCount: number;
  quizCount: number;
  figureCount: number;
  inlineFigureCount: number;
  toc: { id: string; text: string }[];
}

export interface TutorialIndex {
  parts: TutorialPart[];
  chapters: TutorialChapterMeta[];
}

export interface TutorialTocEntry {
  id: string;
  text: string;
  level: number;
}

export interface TutorialExercise {
  id: string;
  kind: string;
  difficulty: number;
  hardware: boolean;
  title: string;
  prompt: string;
  solution: string;
}

export interface TutorialQuizItem {
  id: string;
  stem: string;
  options: string[];
  answer: number;
  explain: string;
}

export interface TutorialCodeFile {
  path: string;
  bytes: number;
  /** Verbatim file contents; the code pages highlight it at build time. */
  content: string;
}

export interface TutorialCodeEntry {
  path: string;
  bytes: number;
}

export interface TutorialFigureMeta {
  id: string;
  title: string;
  section: string | null;
}

export interface TutorialChapter {
  slug: string;
  number: string;
  title: string;
  summary: string;
  words: number;
  readingMinutes: number;
  toc: TutorialTocEntry[];
  html: string;
  /** The chapter's own `references.md`, with the same link rewriting applied. */
  referencesHtml: string;
  codeFiles: TutorialCodeEntry[];
  exercises: TutorialExercise[];
  quiz: TutorialQuizItem[];
  figures: TutorialFigureMeta[];
}

export const TUTORIAL: TutorialIndex = indexJson;

/** Chapter metadata for one slug, or `undefined` when the slug is unknown. */
export function chapterMeta(slug: string): TutorialChapterMeta | undefined {
  return TUTORIAL.chapters.find((chapter) => chapter.slug === slug);
}

/** The part a chapter belongs to, matched on the two-digit chapter number. */
export function partOf(slug: string): TutorialPart | undefined {
  const meta = chapterMeta(slug);
  if (meta === undefined) return undefined;
  return TUTORIAL.parts.find((part) => meta.number >= part.from && meta.number <= part.to);
}

/** Previous/next chapter in reading order. */
export function siblings(slug: string): {
  previous: TutorialChapterMeta | undefined;
  next: TutorialChapterMeta | undefined;
} {
  const index = TUTORIAL.chapters.findIndex((chapter) => chapter.slug === slug);
  if (index < 0) return { previous: undefined, next: undefined };
  return {
    previous: index > 0 ? TUTORIAL.chapters[index - 1] : undefined,
    next: index < TUTORIAL.chapters.length - 1 ? TUTORIAL.chapters[index + 1] : undefined,
  };
}

export function chaptersOfPart(part: TutorialPart): TutorialChapterMeta[] {
  return TUTORIAL.chapters.filter(
    (chapter) => chapter.number >= part.from && chapter.number <= part.to,
  );
}

export const TUTORIAL_ROOT = '';

export function chapterPath(slug: string): string {
  return `${TUTORIAL_ROOT}/${slug}/`;
}
